"""Generate the distributable producer-pack registry from governed definitions."""

from __future__ import annotations

import json
import sys
from pathlib import Path

from adapters.producer.packs import load_query_packs, pack_as_dict

OUTPUT = Path("contracts/generated/producer-packs.json")
CHECK_FLAG = "--check"


def render(root: Path) -> str:
    """Render every pack, exact query, and governed digest deterministically."""
    packs = load_query_packs(root)
    document = {
        "note": (
            "Generated by `make generate-producer-packs` from contracts/amc/query-packs, "
            "data contracts, and Semantic V2 source packs. Do not edit."
        ),
        "packs": [pack_as_dict(pack) for pack in packs],
        # 2: the first pack declaring non-default ADR-110 fields (periodPolicy, inputParameters,
        # suppressionPolicy) changed the projection; the one bump ADR-110 and C-2 reserve.
        "schemaVersion": 2,
    }
    return json.dumps(document, indent=2, sort_keys=True) + "\n"


def main(argv: list[str] | None = None) -> int:
    """Write the registry or fail when the committed projection is stale."""
    arguments = sys.argv[1:] if argv is None else argv
    checking = CHECK_FLAG in arguments
    root = Path.cwd()
    rendered = render(root)
    count = len(load_query_packs(root))

    print("PRODUCER PACK GENERATION")
    print("=" * 60)
    print(f"  packs: {count}")
    if checking:
        if not OUTPUT.is_file():
            print(f"\n{OUTPUT} is missing. Run `make generate-producer-packs`.")
            return 1
        if OUTPUT.read_text() != rendered:
            print(f"\n{OUTPUT} is stale. Run `make generate-producer-packs`.")
            return 1
        print(f"\n{OUTPUT} matches every governed producer artifact.")
        return 0

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(rendered)
    print(f"\nwrote {OUTPUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
